 "<i lang=\"it\" translate=\"no\">scrivere</i>": "<i lang=\"it\" translate=\"no\">scrivere</i>",
 "<i lang=\"it\" translate=\"no\">scritto</i>": "<i lang=\"it\" translate=\"no\">scritto</i>",
